DERIVE = {"user-32": ("user", 20), "bank-32": ("bank", 24)}


def convert(src):
    vb = re.search(r'viewBox="([^"]+)"', src).group(1)
    paths = []
    for m in re.finditer(r"<path\b([^>]*)/?>", src):
        a = m.group(1)
        d = re.search(r'\sd="([^"]+)"', " " + a).group(1)
        stroke = re.search(r'stroke="(#[0-9A-Fa-f]+)"', a)
        fill = re.search(r'fill="(#[0-9A-Fa-f]+)"', a)
        if stroke:
            sw = re.search(r'stroke-width="([^"]+)"', a)
            lj = re.search(r'stroke-linejoin="([^"]+)"', a)
            lc = re.search(r'stroke-linecap="([^"]+)"', a)
            extra = ' stroke-width="%s"' % (sw.group(1) if sw else "2") + (' stroke-linejoin="%s"' % lj.group(1) if lj else "") + (' stroke-linecap="%s"' % lc.group(1) if lc else "")
            paths.append('<path fill="none" stroke="currentColor"%s d="%s"/>' % (extra, d))
        elif fill:
            fr = re.search(r'fill-rule="([^"]+)"', a)
            paths.append('<path fill="currentColor"%s d="%s"/>' % (' fill-rule="%s"' % fr.group(1) if fr else "", d))
    assert paths, "no paths"
    return '<svg viewBox="%s">%s</svg>' % (vb, "".join(paths))


d = json.load(open(P, encoding="utf-8"))
for name in sys.argv[1:]:
    if name in DERIVE:  # a 32 px use of a 24 (or 20) px master: Figma keeps the stroke at 2 px, so the stroke in master units is 2 * master / 32
        base, vb = DERIVE[name]
        d[name] = d[base].replace('stroke-width="2"', 'stroke-width="%s"' % round(2 * vb / 32, 3))
        assert 'stroke-width="%s"' % round(2 * vb / 32, 3) in d[name]
    elif name in MANUAL:
        d[name] = MANUAL[name]
    else:
        d[name] = convert(open(os.path.join(DL, name + ".svg"), encoding="utf-8").read())
    print(name, len(d[name]), "bytes")
json.dump(d, open(P, "w", encoding="utf-8"), ensure_ascii=False)
print("icons:", len(d))
